namespace ghidra.app.plugin.core.datamgr.actions;



using docking;
using docking.action;
using docking.action;
using docking.widgets.tree;
using docking.widgets.tree;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.editor;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.program.model.data;
using ghidra.program.model.dtarchive;

/**
 * Action to set an archive to be read only
 */
public class CloseArchiveForEditingAction : DockingAction {
	public static readonly string ACTION_NAME = "Close Archive For Editing";

	private DataTypeManagerPlugin plugin;

	public CloseArchiveForEditingAction(DataTypeManagerPlugin plugin) : base(ACTION_NAME, plugin.getName())
    {
		this.plugin = plugin;

		setPopupMenuData(new MenuData(new string[] { "Close For Editing" }, null, "FileEdit"));

		setEnabled(true);
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		if (!(context is DataTypesActionContext)) {
			return false;
		}

		TreePath[] selectionPaths = getSelectionPaths(context);
		return isOnlyFileArchivesSelected(selectionPaths);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is DataTypesActionContext)) {
			return false;
		}

		TreePath[] selectionPaths = getSelectionPaths(context);
		return isOnlyFileArchivesSelected(selectionPaths) &&
			isOneOrMoreSelectedFileArchivesLocked(selectionPaths);
	}

	private bool isOnlyFileArchivesSelected(TreePath[] selectionPaths) {
		// only valid if all selected paths are file archives
		if (selectionPaths.length == 0) {
			return false;
		}
		foreach (TreePath path in selectionPaths) {
			GTreeNode node = (GTreeNode) path.getLastPathComponent();
			if (!(node is FileArchiveNode)) {
				return false;
			}
		}

		return true;
	}

	private bool isOneOrMoreSelectedFileArchivesLocked(TreePath[] selectionPaths) {
		// only valid if all selected paths are file archives
		foreach (TreePath path in selectionPaths) {
			GTreeNode node = (GTreeNode) path.getLastPathComponent();
			if (isModifiable((FileArchiveNode) node)) {
				return true;
			}
		}
		return false;
	}

	private TreePath[] getSelectionPaths(ActionContext context) {
		object contextObject = context.getContextObject();
		GTree gtree = (GTree) contextObject;
		TreePath[] selectionPaths = gtree.getSelectionPaths();
		return selectionPaths;
	}

	private bool isModifiable(FileArchiveNode fileArchiveNode) {
		FileDataTypeArchive archive = fileArchiveNode.getArchive();
		return archive.isChangeable();
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		GTree gTree = (GTree) context.getContextObject();

		TreePath[] selectionPaths = gTree.getSelectionPaths();
		DataTypeEditorManager editorManager = plugin.getEditorManager();
		foreach (TreePath path in selectionPaths) {
			FileArchiveNode node = (FileArchiveNode) path.getLastPathComponent();
			FileDataTypeArchive archive = node.getArchive();

			DataTypeManager dataTypeManager = archive.getDataTypeManager();
			if (!editorManager.checkEditors(dataTypeManager, true)) {
				return;
			}
			// check for changes and save if desired by user. If cancelled, get out.
			if (!plugin.resolveModifiedArchive(archive)) {
				return;
			}
			editorManager.dismissEditors(dataTypeManager);
			ArchiveManager archiveManager = plugin.getArchiveManager();
			archiveManager.reopenFileArchive(archive, false);
		}
	}
}
